pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    let trimmed = bytes.trim();
    if !trimmed.starts_with('{') && bytes.contains("ping") {
        return Ok(Msg::Ping);
    }

    let fields = parse_object(bytes)?;
    if fields.get("v").map(String::as_str) != Some("2") {
        return Err("unsupported version".into());
    }
    if fields.get("type").map(String::as_str) != Some("hello") {
        return Err("unknown message type".into());
    }

    fields
        .get("value")
        .cloned()
        .ok_or_else(|| "missing hello value".into())
        .map(Msg::Hello)
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!(
            "{{\"v\":2,\"type\":\"hello\",\"value\":{}}}",
            quote_json_string(value)
        ),
    }
}

fn quote_json_string(value: &str) -> String {
    let mut quoted = String::with_capacity(value.len() + 2);
    quoted.push('"');
    for byte in value.bytes() {
        match byte {
            b'"' => quoted.push_str("\\\""),
            b'\\' => quoted.push_str("\\\\"),
            b'\n' => quoted.push_str("\\n"),
            b'\r' => quoted.push_str("\\r"),
            b'\t' => quoted.push_str("\\t"),
            0x00..=0x1f => quoted.push_str(&format!("\\u{:04x}", byte)),
            _ => quoted.push(byte as char),
        }
    }
    quoted.push('"');
    quoted
}

fn parse_object(input: &str) -> Result<std::collections::BTreeMap<String, String>, String> {
    let input = input.trim();
    let inner = input
        .strip_prefix('{')
        .and_then(|value| value.strip_suffix('}'))
        .ok_or_else(|| "invalid envelope".to_string())?
        .trim();
    let mut fields = std::collections::BTreeMap::new();

    if inner.is_empty() {
        return Ok(fields);
    }

    for member in split_members(inner)? {
        let (key, value) = member
            .split_once(':')
            .ok_or_else(|| "invalid envelope member".to_string())?;
        let key = parse_json_string(key.trim())?;
        let value = value.trim();
        let value = if key == "v" {
            value.to_string()
        } else {
            parse_json_string(value)?
        };
        if fields.insert(key, value).is_some() {
            return Err("duplicate envelope field".into());
        }
    }

    Ok(fields)
}

fn split_members(input: &str) -> Result<Vec<&str>, String> {
    let mut members = Vec::new();
    let mut start = 0;
    let mut in_string = false;
    let mut escaped = false;

    for (index, byte) in input.bytes().enumerate() {
        if in_string {
            if escaped {
                escaped = false;
            } else if byte == b'\\' {
                escaped = true;
            } else if byte == b'"' {
                in_string = false;
            }
        } else if byte == b'"' {
            in_string = true;
        } else if byte == b',' {
            members.push(input[start..index].trim());
            start = index + 1;
        }
    }

    if in_string || escaped {
        return Err("invalid envelope string".into());
    }
    members.push(input[start..].trim());
    Ok(members)
}

fn parse_json_string(input: &str) -> Result<String, String> {
    let bytes = input.as_bytes();
    if bytes.len() < 2 || bytes[0] != b'"' || bytes[bytes.len() - 1] != b'"' {
        return Err("expected JSON string".into());
    }

    let mut value = String::new();
    let mut chars = input[1..bytes.len() - 1].chars();
    while let Some(character) = chars.next() {
        if character != '\\' {
            value.push(character);
            continue;
        }
        match chars.next() {
            Some('"') => value.push('"'),
            Some('\\') => value.push('\\'),
            Some('/') => value.push('/'),
            Some('b') => value.push('\u{0008}'),
            Some('f') => value.push('\u{000c}'),
            Some('n') => value.push('\n'),
            Some('r') => value.push('\r'),
            Some('t') => value.push('\t'),
            Some('u') => return Err("unicode escapes are not supported".into()),
            _ => return Err("invalid JSON escape".into()),
        }
    }
    Ok(value)
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn ping_encode_roundtrip() {
        let encoded = encode(&Msg::Ping);
        assert!(matches!(decode(&encoded), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_uses_v2_envelope() {
        let encoded = encode(&Msg::Hello("example-client".into()));
        assert_eq!(
            encoded,
            "{\"v\":2,\"type\":\"hello\",\"value\":\"example-client\"}"
        );
        assert!(matches!(
            decode(&encoded),
            Ok(Msg::Hello(value)) if value == "example-client"
        ));
    }

    #[test]
    fn hello_value_is_escaped() {
        let message = Msg::Hello("a\"b\\c\nd".into());
        assert!(matches!(decode(&encode(&message)), Ok(Msg::Hello(value)) if value == "a\"b\\c\nd"));
    }

    #[test]
    fn hello_requires_v2_and_type() {
        assert!(decode(r#"{"v":1,"type":"hello","value":"client"}"#).is_err());
        assert!(decode(r#"{"v":2,"type":"ping","value":"client"}"#).is_err());
    }
}
